"""Tool output classification for the browser file list."""

from __future__ import annotations

from pathlib import Path

from teviewer.backends.blast_genome_plot import (
    is_blast_table_file,
    is_divergence_plot_html_file,
    is_genome_map_html_file,
)


def is_tool_output_file(path: Path) -> bool:
    """True when a file is likely generated by a RepeatViewer tool run."""
    name = path.name.lower()
    if name.endswith("_blastp.txt"):
        return True
    if name.endswith("_blast.gff"):
        return True
    if name.endswith(".gff.colors.config"):
        return True
    if name.endswith("_legend.png") and "_flexidot" in name:
        return True
    if name.endswith("_blast.txt.fa"):
        return True
    if name.endswith(".tsd_search.txt"):
        return True
    if name.endswith(".lnk.fa"):
        return True
    if is_blast_table_file(path):
        return True
    if is_genome_map_html_file(path) or is_divergence_plot_html_file(path):
        return True
    if name.endswith("_sankey.html") or "confusion_matrix" in name:
        return True
    if "_flexidot" in name and name.endswith(".png"):
        return True
    if name.endswith((".aln", ".mafft", ".clustal", ".stockholm")):
        return True
    if name.endswith((".html", ".htm")) and any(
        token in name for token in ("_teaid", "_tea_id", "teaid", "_benchmark")
    ):
        return True
    if name.endswith(".out"):
        return True
    if name.endswith(".bed") and "_blast" in name:
        return True
    return False
